\begin{definition}[Two-round threshold signature with offline first round]
A \emph{two-round threshold signature scheme with offline first round} for $N$ signers and threshold $T$ is a tuple $\mathsf{TS} = (\mathsf{KeyGen}, \mathsf{Sign}_1, \mathsf{Sign}_2, \mathsf{Combine}, \mathsf{Ver})$ of polynomial-time algorithms, all of which take the public key $\mathsf{pk}$ implicitly as input:
\begin{itemize}
\item $\mathsf{KeyGen}(1^{\kappa}) \to (\mathsf{pk}, \{\mathsf{sk}_i\}_{i \in [N]})$.
\item $\mathsf{Sign}_1(i, \mathsf{sk}_i, \mathsf{SS}) \to (\mathsf{st}, \mathit{psig}^{(1)}_i)$, defined for $\mathsf{SS} \subseteq [N]$ with $|\mathsf{SS}| \ge T$ and $i \in \mathsf{SS}$, producing a secret state $\mathsf{st}$ and a first-round protocol message $\mathit{psig}^{(1)}_i$. \emph{The message $\mu$ is not an input to $\mathsf{Sign}_1$; this is what makes the first round offline.}
\item $\mathsf{Sign}_2(i, \mathsf{sk}_i, \mathsf{st}, \mathsf{SS}, \mu, M) \to \mathit{psig}^{(2)}_i$, where $\mu \in \{0,1\}^{*}$ and $M = \{\mathit{psig}^{(1)}_j\}_{j \in \mathsf{SS}}$.
\item $\mathsf{Combine}(\mathsf{SS}, \mu, M, M') \to \mathit{sig}$, where $M' = \{\mathit{psig}^{(2)}_j\}_{j \in \mathsf{SS}}$. $\mathsf{Combine}$ takes no secret input and may be run by any party.
\item $\mathsf{Ver}(\mathsf{pk}, \mu, \mathit{sig}) \to 0/1$.
\end{itemize}
$\mathsf{TS}$ has \emph{correctness error} $\varepsilon_{\mathsf{cor}}$ if for every $\mu \in \{0,1\}^{*}$ and every $\mathsf{SS} \subseteq [N]$ with $|\mathsf{SS}| \ge T$, running $\mathsf{KeyGen}$, then $\mathsf{Sign}_1$ for every $i \in \mathsf{SS}$, then $\mathsf{Sign}_2$ for every $i \in \mathsf{SS}$ on the resulting $M$, then $\mathsf{Combine}$, yields $\mathit{sig}$ with $\mathsf{Ver}(\mathsf{pk}, \mu, \mathit{sig}) = 1$ except with probability at most $\varepsilon_{\mathsf{cor}}(\kappa)$.
\end{definition}

\begin{definition}[Adaptive unforgeability, $\mathrm{adp}\text{-}\mathrm{TSUF}$]
Let $\mathsf{TS}$ be as in Definition~1 and let $H$ be a random oracle. The game $\mathrm{adp}\text{-}\mathrm{TSUF}^{\mathcal{A}}_{\mathsf{TS}[N,T]}(\kappa)$ initialises $S \gets \emptyset$, $\mathsf{CS} \gets \emptyset$, samples $(\mathsf{pk}, \{\mathsf{sk}_i\}_{i \in [N]}) \gets \mathsf{KeyGen}(1^{\kappa})$, and for each $i \in [N]$ sets a counter $\mathsf{st}_i.\mathsf{cnt} \gets 0$, an empty table $\mathsf{st}_i.\mathsf{P}$ of per-session states, and $\mathsf{st}_i.\mathsf{sk} \gets \mathsf{sk}_i$. It runs $\mathcal{A}(\mathsf{pk})$ with access to:
\begin{itemize}
\item $\mathrm{oSign}_1(i, \mathsf{SS})$: requires $i \in \mathsf{SS} \setminus \mathsf{CS}$, $\mathsf{SS} \subseteq [N]$, $|\mathsf{SS}| \ge T$. Sets $\mathsf{st}_i.\mathsf{cnt} \gets \mathsf{st}_i.\mathsf{cnt} + 1$, runs $(\mathit{psig}^{(1)}, \mathsf{st}) \gets \mathsf{Sign}_1(i, \mathsf{sk}_i, \mathsf{SS})$, stores $\mathsf{st}_i.\mathsf{P}(\mathsf{st}_i.\mathsf{cnt}) \gets (0, \mathsf{st}, \mathsf{SS})$, and returns $\mathit{psig}^{(1)}$.
\item $\mathrm{oSign}_2(i, \mathit{sid}, \mathsf{SS}, \mu, M)$: requires $i \in \mathsf{SS} \setminus \mathsf{CS}$, $\mathit{sid} \le \mathsf{st}_i.\mathsf{cnt}$, $\mathsf{SS} \subseteq [N]$, $|\mathsf{SS}| \ge T$. Parses $(\mathit{isUsed}, \mathsf{st}, \mathsf{SS}') \gets \mathsf{st}_i.\mathsf{P}(\mathit{sid})$ and returns $\bot$ if $\mathit{isUsed} = 1$ or $\mathsf{SS}' \ne \mathsf{SS}$. Otherwise it sets $S \gets S \cup \{\mu\}$ and $\mathsf{st}_i.\mathsf{P}(\mathit{sid}) \gets (1, \mathsf{st}, \mathsf{SS})$, and returns $\mathit{psig}^{(2)} \gets \mathsf{Sign}_2(i, \mathsf{sk}_i, \mathsf{st}, \mathsf{SS}, \mu, M)$.
\item $\mathrm{Cor}(i)$: requires $|\mathsf{CS}| < T - 1$. Sets $\mathsf{CS} \gets \mathsf{CS} \cup \{i\}$ and returns the whole of $\mathsf{st}_i$, i.e. the secret-key share $\mathsf{sk}_i$ together with the stored state of \emph{every} session of signer $i$, used or unused. (There are no erasures, and signers keep no state beyond $\mathsf{sk}_i$ and these per-session states.)
\item $H$.
\end{itemize}
When $\mathcal{A}$ halts with output $(\mu, \mathit{sig})$, the game returns $1$ if $|\mathsf{CS}| \le T-1$, $\mu \notin S$ and $\mathsf{Ver}(\mathsf{pk}, \mu, \mathit{sig}) = 1$, and $0$ otherwise. Write $\mathrm{Adv}^{\mathrm{adp\text{-}tsuf}}_{\mathsf{TS}[N,T]}(\mathcal{A},\kappa) := \Pr[\mathrm{adp}\text{-}\mathrm{TSUF}^{\mathcal{A}}_{\mathsf{TS}[N,T]}(\kappa) = 1]$.
\end{definition}

\begin{definition}[MLWE and MSIS]
Fix $d, q, k, m, \beta$ and let $\mathcal{R}_q$, $\mathcal{B}_\beta$ be as in the notation.
\begin{itemize}
\item $\mathrm{MSIS}_{q,d,k,m,\beta}$: sample $\mathbf{A} \gets \mathcal{R}_q^{k \times m}$ and give it to $\mathcal{C}$, which outputs $\mathbf{x} \in \mathcal{R}^{m}$; $\mathcal{C}$ wins if $\mathbf{x} \ne \mathbf{0}$, $\|\mathbf{x}\| \le \beta$ and $\mathbf{A}\mathbf{x} = \mathbf{0} \bmod q$. Write $\mathrm{Adv}^{\mathrm{msis}}_{q,d,k,m,\beta}(\mathcal{C},\kappa)$ for the winning probability.
\item $\mathrm{MLWE}_{q,d,k,m,\beta}$: sample $\mathbf{A}' \gets \mathcal{R}_q^{k \times (m-k)}$, set $\mathbf{A} := [\mathbf{A}' \mid \mathbf{I}_k]$, sample $\mathbf{s} \gets \mathcal{B}_\beta^{m}$, set $\mathbf{t}_0 := \mathbf{A}\mathbf{s}$, sample $\mathbf{t}_1 \gets \mathcal{R}_q^{k}$ and $b \gets \{0,1\}$, and give $(\mathbf{A}, \mathbf{t}_b)$ to $\mathcal{B}$, which outputs a guess $\tilde{b}$. Write $\mathrm{Adv}^{\mathrm{mlwe}}_{q,d,k,m,\beta}(\mathcal{B},\kappa) := |\Pr[\tilde{b} = b] - 1/2|$.
\end{itemize}
\end{definition}
